<div class="col-12 d-flex gap-2"><button class="btn btn-primary">Guardar encomenda</button><a class="btn btn-outline-secondary" href="<?=h(so_url($id?['id'=>$id]:[]))?>">Cancelar</a></div>
</form><?php endif;?></div></section>
