<div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>OF</th><th>Artigo</th><th>Prevista</th><th>Realizada</th><th>Data prevista</th><th>Estado</th><th>Progresso</th></tr></thead><tbody><?php foreach($ofs as $of):?><tr><td><a href="production_dossier.php?id=<?=(int)$of['id']?>"><?=h($of['order_number'])?></a></td><td><?=h($of['article_code'])?></td><td><?=h(so_number($of['planned_quantity']).' '.$of['unit_code'])?></td><td><?=h(so_number($of['produced_quantity']).' '.$of['unit_code'])?></td><td><?=h(so_date($of['due_date']))?></td><td><?=h($of['status'])?></td><td><?=h($of['planned_quantity']>0?so_number(100*$of['produced_quantity']/$of['planned_quantity'],1).' %':'Sem dados')?></td></tr><?php endforeach;if(!$ofs):?><tr><td colspan="7" class="text-secondary py-4">Sem OF associadas.</td></tr><?php endif;?></tbody></table></div>
